package ui

import "github.com/charmbracelet/x/vt"

// startTerminalResponseReader forwards replies generated by the VT emulator
// (for example cursor-position and color queries) back to the connected PTY.
// The reader must run before the first terminal.Write: the emulator writes
// replies through an io.Pipe and blocks until this goroutine consumes them.
func startTerminalResponseReader(pane *terminalPane) {
	if pane == nil || pane.session == nil || pane.terminal == nil || pane.terminalResponseReaderStarted {
		return
	}
	terminal := pane.terminal
	session := pane.session
	pane.terminalResponseReaderStarted = true
	go func() {
		buffer := make([]byte, 4096)
		for {
			n, err := terminal.Read(buffer)
			if n > 0 {
				if writeErr := session.Write(buffer[:n]); writeErr != nil {
					return
				}
			}
			if err != nil {
				return
			}
		}
	}()
}

// drainTerminalResponses keeps noninteractive VT previews from blocking when
// their stored output contains a terminal query whose reply is irrelevant.
func drainTerminalResponses(terminal *vt.SafeEmulator) {
	if terminal == nil {
		return
	}
	go func() {
		buffer := make([]byte, 4096)
		for {
			if _, err := terminal.Read(buffer); err != nil {
				return
			}
		}
	}()
}

func closeTerminalResponseReader(pane *terminalPane) {
	if pane == nil || pane.terminal == nil || !pane.terminalResponseReaderStarted {
		return
	}
	// Closing the emulator's response pipe releases its one blocked reader.
	_ = pane.terminal.Close()
	pane.terminalResponseReaderStarted = false
}
